import sys

MOD = 10**9 + 7

def count_ways(words):
    def remove_letter(word, i):
        return word[:i] + word[i+1:]

    def dp(i, prev_word):
        if i == len(words):
            return 1
        current_word = words[i]
        count = 0
        for j in range(len(current_word)):
            new_word = remove_letter(current_word, j)
            if new_word >= prev_word:
                count += dp(i + 1, new_word)
                count %= MOD
        return count

    return dp(0, "")

n = int(sys.stdin.readline().strip())
words = [sys.stdin.readline().strip() for _ in range(n)]

print(count_ways(words))
